using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
namespace kok {
 public sealed class EmbeddingConfig {public bool enabled;public string endpoint="http://127.0.0.1:11434",model="",revision="1";public double minimumSimilarity=.35;}
 public sealed class KnowledgeSearchResult {public string mode,notice="";public List<ContentHit> hits=new List<ContentHit>();public List<string> ids=new List<string>();}
 public sealed class LocalEmbedder {
  readonly Func<HttpMessageHandler> factory;
  public LocalEmbedder(Func<HttpMessageHandler> factory=null){this.factory=factory;}
  public static Uri Endpoint(string value){Uri u;if(!Uri.TryCreate(value,UriKind.Absolute,out u)||!u.IsLoopback||u.Scheme!="http"&&u.Scheme!="https"||u.UserInfo!=""||u.Query!=""||u.Fragment!=""||u.AbsolutePath!="/"&&u.AbsolutePath!="/api/embed")throw new InvalidDataException("Embeddings require a local Ollama endpoint without credentials or query parameters.");return new Uri(u.GetLeftPart(UriPartial.Authority)+"/api/embed");}
  public static double[] Normalize(double[] values){if(values==null||values.Length<2||values.Length>16384||values.Any(v=>Double.IsNaN(v)||Double.IsInfinity(v)||Math.Abs(v)>1e10))throw new InvalidDataException("Embedding service returned an invalid vector.");double norm=Math.Sqrt(values.Sum(v=>v*v));if(norm<1e-12)throw new InvalidDataException("Embedding service returned an empty vector.");return values.Select(v=>v/norm).ToArray();}
  public async Task<List<double[]>> Embed(EmbeddingConfig c,IList<string> text,CancellationToken token){
   using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(token)){deadline.CancelAfter(45000);token=deadline.Token;
   if(text==null||text.Count<1||text.Count>24||text.Any(t=>t==null||t.Length>16000))throw new InvalidDataException("Invalid embedding batch.");var endpoint=Endpoint(c.endpoint);
   using(var handler=factory==null?new HttpClientHandler{AllowAutoRedirect=false,UseProxy=false}:factory())using(var client=new HttpClient(handler)){client.Timeout=TimeSpan.FromSeconds(45);using(var request=new HttpRequestMessage(HttpMethod.Post,endpoint)){request.Content=new StringContent(Library.Json.Serialize(new{model=c.model,input=text,truncate=false}),Encoding.UTF8,"application/json");using(var response=await client.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token)){if(!response.IsSuccessStatusCode)throw new IOException("Local embedding service is unavailable or its model is not installed.");using(var stream=await response.Content.ReadAsStreamAsync())using(var memory=new MemoryStream()){var bytes=new byte[8192];int read;while((read=await stream.ReadAsync(bytes,0,bytes.Length,token))>0){if(memory.Length+read>8*1024*1024)throw new InvalidDataException("Embedding response is too large.");memory.Write(bytes,0,read);}var value=Library.Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(memory.ToArray()));var vectors=AgentTaskState.Get<List<double[]>>(value,"embeddings");if(vectors==null||vectors.Count!=text.Count)throw new InvalidDataException("Embedding service returned the wrong batch size.");var result=vectors.Select(Normalize).ToList();if(result.Any(v=>v.Length!=result[0].Length))throw new InvalidDataException("Embedding vector dimensions differ.");return result;}}}}
   }
  }
 }
 public partial class Library {
  public EmbeddingConfig ReadEmbeddingConfig(){EnsureNormalContent();string path=Path.Combine(DataDir,"embedding-settings.json");lock(gate){if(!File.Exists(path))return new EmbeddingConfig();var c=Json.Deserialize<EmbeddingConfig>(File.ReadAllText(path,Encoding.UTF8));ValidateEmbeddingConfig(c);return c;}}
  static void ValidateEmbeddingConfig(EmbeddingConfig c){if(c==null||c.model==null||c.model.Length>200||c.enabled&&String.IsNullOrWhiteSpace(c.model)||c.revision==null||c.revision.Length>100||Double.IsNaN(c.minimumSimilarity)||Double.IsInfinity(c.minimumSimilarity)||c.minimumSimilarity<0||c.minimumSimilarity>1)throw new InvalidDataException("Invalid embedding configuration.");LocalEmbedder.Endpoint(c.endpoint);}
  public EmbeddingConfig SaveEmbeddingConfig(EmbeddingConfig c){EnsureNormalContent();ValidateEmbeddingConfig(c);lock(gate){string file=Path.Combine(DataDir,"embedding-settings.json"),temp=file+".tmp";File.WriteAllText(temp,Json.Serialize(c),new UTF8Encoding(false));if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}return c;}
  internal static string EmbeddingKey(EmbeddingConfig c){return StudyHash(new{provider="ollama",endpoint=LocalEmbedder.Endpoint(c.endpoint).AbsoluteUri,c.model,c.revision,chunkVersion=1});}
  public async Task<object> BuildEmbeddings(CancellationToken token,Action<int,int> progress=null,LocalEmbedder embedder=null,Action validate=null){RequireAiMode();var cfg=ReadEmbeddingConfig();if(!cfg.enabled)throw new InvalidOperationException("Enable a local embedding model first.");string key=EmbeddingKey(cfg);var ids=ContentEntries().Select(e=>e.id).ToArray();var chunks=ReadContentChunks(ids);var existing=new HashSet<string>(ReadVectors(key,ids).Select(v=>v.chunkId));var pending=chunks.Where(c=>!existing.Contains(c.id)).ToList();int done=0;embedder=embedder??new LocalEmbedder();for(int n=0;n<pending.Count;n+=16){token.ThrowIfCancellationRequested();validate?.Invoke();RequireAiMode();if(EmbeddingKey(ReadEmbeddingConfig())!=key||!ReadEmbeddingConfig().enabled)throw new OperationCanceledException();var batch=pending.Skip(n).Take(16).ToList();var vectors=await embedder.Embed(cfg,batch.Select(c=>c.text).ToArray(),token);validate?.Invoke();token.ThrowIfCancellationRequested();RequireAiMode();if(EmbeddingKey(ReadEmbeddingConfig())!=key||!ReadEmbeddingConfig().enabled)throw new OperationCanceledException();WriteVectors(batch.Select((c,i)=>new ContentVector{chunkId=c.id,model=key,values=vectors[i]}).ToList(),batch.GroupBy(c=>c.itemId).ToDictionary(g=>g.Key,g=>g.First().stamp));done+=batch.Count;progress?.Invoke(done,pending.Count);}return new{embedded=done,cached=existing.Count,total=chunks.Count};}
  public async Task<KnowledgeSearchResult> SearchKnowledge(string query,IEnumerable<string> allowed,string mode,int limit,CancellationToken token,LocalEmbedder embedder=null,Action validate=null){
   EnsureNormalContent();query=(query??"").Trim();if(query.Length>200||!new[]{"lexical","hybrid","semantic"}.Contains(mode)||limit<1||limit>500)throw new InvalidDataException("Invalid knowledge search query.");var result=new KnowledgeSearchResult{mode=mode};if(query.Length==0)return result;HashSet<string> scope;List<ContentChunk> lexical;List<string> fileMatches;lock(gate){InvalidateChangedContent();scope=new HashSet<string>((allowed??Db.items.Select(e=>e.id)).Where(id=>Find(id)!=null));lexical=store.MatchContent(query,scope,limit*4);fileMatches=store.Search(query).Where(scope.Contains).ToList();}
   var scores=new Dictionary<string,double>();var candidates=new Dictionary<string,ContentChunk>();int position=0;foreach(var c in lexical){candidates[c.id]=c;scores[c.id]=1d/(60+ ++position);}
   if(mode!="lexical"){
    RequireAiMode();var cfg=ReadEmbeddingConfig();if(!cfg.enabled){result.notice="No local embedding model is enabled. Using lexical results.";result.mode="lexical";}
    else try{validate?.Invoke();var key=EmbeddingKey(cfg);var vectors=ReadVectors(key,scope);if(vectors.Count==0){result.notice="Build the semantic index first. Using lexical results.";result.mode="lexical";}else{var q=(await (embedder??new LocalEmbedder()).Embed(cfg,new[]{query},token))[0];validate?.Invoke();token.ThrowIfCancellationRequested();RequireAiMode();if(!ReadEmbeddingConfig().enabled||EmbeddingKey(ReadEmbeddingConfig())!=key)throw new OperationCanceledException();if(vectors.Any(v=>v.values.Length!=q.Length))throw new InvalidDataException("Embedding dimensions changed; rebuild with a new revision.");var chunks=ReadContentChunks(scope).ToDictionary(c=>c.id);var ranked=vectors.Where(v=>v.values.Length==q.Length&&chunks.ContainsKey(v.chunkId)).Select(v=>new{c=chunks[v.chunkId],score=v.values.Zip(q,(a,b)=>a*b).Sum()}).Where(v=>v.score>=cfg.minimumSimilarity).OrderByDescending(v=>v.score).Take(limit*4).ToList();if(mode=="semantic"){scores.Clear();candidates.Clear();fileMatches.Clear();}position=0;foreach(var v in ranked){candidates[v.c.id]=v.c;double prior;scores[v.c.id]=(scores.TryGetValue(v.c.id,out prior)?prior:0)+1d/(60+ ++position);}}}
    catch(Exception ex)when(ex is HttpRequestException||ex is IOException||ex is InvalidDataException||ex is TaskCanceledException&&!token.IsCancellationRequested){result.notice="Local embeddings are unavailable. Using lexical results.";result.mode="lexical";}
   }
   lock(gate){foreach(var id in fileMatches){var item=Find(id);if(item==null)continue;var candidate=candidates.Values.FirstOrDefault(c=>c.itemId==id);if(candidate==null){string key="item:"+id;candidates[key]=new ContentChunk{id="",itemId=id,kind="metadata",text=item.name+"\n"+SearchContent.Metadata(item),anchor=new SourceAnchor{itemId=id},stamp=ContentStamp(id)};scores[key]=1d/60;}}var seenItems=new HashSet<string>();foreach(var pair in candidates.Where(p=>scores.ContainsKey(p.Key)).OrderByDescending(p=>scores[p.Key])){var c=pair.Value;var e=Find(c.itemId);if(e==null||!scope.Contains(e.id)||ContentStamp(e.id)!=c.stamp||!seenItems.Add(e.id))continue;result.hits.Add(new ContentHit{itemId=e.id,chunkId=c.id,name=e.name,text=c.text.Length>1200?c.text.Substring(0,1200):c.text,kind=c.kind,clipId=c.clipId,anchor=c.anchor,score=scores[pair.Key]});if(result.hits.Count>=limit)break;}result.ids=result.hits.Select(h=>h.itemId).Distinct().ToList();}return result;
  }
 }
}
